  await page.reload();
  await expect(page.getByLabel("Status")).toHaveValue("OPEN");
  await expect(page.getByLabel("Szukaj")).toHaveValue("api");
  await expect(rows).toHaveCount(1);
  await expect(rows.first()).toContainText("API timeout");
});
